export type ExtensionGlyphName = keyof typeof glyphs;

export function ExtensionGlyph({ name, size = 16, color = 'currentColor', style }: {
  name: ExtensionGlyphName;
  size?: number;
  color?: string;
  style?: CSSProperties;
}) {
  const glyph = glyphs[name][size >= 20 ? 20 : 16];
  return <svg width={size} height={size} viewBox={glyph.viewBox} fill="none" style={style} aria-hidden="true" focusable="false" data-codex-icon={glyph.name}>
    {glyph.paths.map((path, index) => <path key={index} {...path} fill={color} />)}
  </svg>;
}

// Skill artwork is copied without edits from the default light/dark assets
// in webview/assets/text-bubble-figure-light-c974e4c8b638.js.
const skillLight = new URL('../../../assets/codex-skill-light.svg', import.meta.url).href;
const skillDark = new URL('../../../assets/codex-skill-dark.svg', import.meta.url).href;

export function ExtensionSkillArtwork() {
  const t = useT();
  return <img src={t.dark ? skillDark : skillLight} width={24} height={24} alt="" aria-hidden="true" draggable={false} />;
}
